TAIL = "\n\nInfoImobiliária, by OMNI".replace("InfoImobiliária", "Info Imobiliária")
LINK = "infoimobiliaria.com\n(Link também na bio.)"
def cap(lines, fonte, tags, leg=True):
    t = "\n".join(lines) + "\n\n" + LINK
    if fonte: t += "\n\nFonte: " + fonte
    if leg: t += "\n" + LEG
    return t + TAIL + "\n\n" + " ".join(tags)
