# horas locais (Lisboa = UTC em novembro; confirmado por zoneinfo)
T = {10: ("10:15", "13:30", "20:00", "12:00", "16:30"), 11: ("09:45", "14:15", "19:30", "11:30", "17:00"),
     12: ("10:45", "13:00", "20:30", "12:30", "15:45"), 13: ("09:15", "14:45", "19:15", "11:15", "16:15"),
     14: ("11:00", "15:00", "20:15", "13:15", "17:30"), 15: ("10:30", "14:00", "19:00", "12:15", "16:00"),
     16: ("09:30", "13:45", "20:45", "11:45", "15:30")}
def utc(day, hhmm, add=0):
    h, m = map(int, hhmm.split(":"))
    d = dt.datetime(2026, 11, day, h, m, tzinfo=ZoneInfo("Europe/Lisbon")) + dt.timedelta(minutes=add)
    return d.astimezone(dt.timezone.utc).strftime("%Y-%m-%dT%H:%M:00.000Z")
plan = []
for day, (a, b, c, ca, im) in T.items():
    for n, t in zip(("v1", "v2", "v3"), (a, b, c)):
        k = f"d{day}{n}"; plan.append(dict(key=k, kind="video", at=utc(day, t), story_at=utc(day, t, 25), title=M[k][0], text=M[k][1]))
    k = f"d{day}c"; plan.append(dict(key=k, kind="carousel", at=utc(day, ca), story_at=[utc(day, ca, 30 + 12 * i) for i in range(5)], text=M[k][1]))
    k = f"d{day}i"; plan.append(dict(key=k, kind="image", at=utc(day, im), story_at=utc(day, im, 30), text=M[k][1]))
json.dump(plan, open("plan.json", "w"), ensure_ascii=False, indent=1)
assert not any("—" in p["text"] or "—" in (p.get("title") or "") for p in plan)
assert all(len(p.get("title") or "") <= 100 for p in plan)
print(len(plan), plan[0]["at"], plan[-1]["at"])
